// @ts-check
const { defineConfig, devices } = require('@playwright/test');

/**
 * Read environment variables from file.
 * https://github.com/motdotla/dotenv
 */
// require('dotenv').config();

/**
 * @see https://playwright.dev/docs/test-configuration
 */
module.exports = defineConfig({
  testDir: './e2e',
  /* E2E tests are defined in *.spec.js files while unit tests are defined in *.test.js files.
   * Playwright should only run the *.spec.js files.
   */
  testMatch: '**/*.spec.js',
  // Halved from 60000 on 2026-07-16 — with retries: 2 below, a genuinely
  // hung/never-found-element failure was costing 3 * 60s = 180s per test
  // in CI. 30s is still generous for the one spec file that exists today
  // (homepage smoke, ~2-8s on a healthy pass) — revisit if a slower,
  // legitimately-long-running spec (e.g. a full checkout flow) is added.
  timeout: 30000,
  /* Run tests in files in parallel */
  fullyParallel: true,
  /* Fail the build on CI if you accidentally left test.only in the source code. */
  forbidOnly: !!process.env.CI,
  /* Retry on CI only */
  retries: 2,
  /* Opt out of parallel tests on CI. */
  workers: 1,
  /* Reporter to use. See https://playwright.dev/docs/test-reporters */
  // 'list' alone never writes anything to disk — only the p0 project below
  // overrode this with an html reporter, so every other project (chromium,
  // mobile-chrome, a11y-*, extra-features-*) left playwright-report/ empty
  // on every run, CI included. qa.yml's "Upload Playwright report" artifact
  // had genuinely nothing to upload for e2e-localhost failures as a result.
  // Adding html here (open: 'never' — CI/scripted runs shouldn't try to
  // launch a browser tab) gives every project a real, inspectable report.
  reporter: [['list'], ['html', { open: 'never' }]],
  /* Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions. */
  use: {
    /* Base URL to use in actions like `await page.goto('/')`. */
    // baseURL: 'http://127.0.0.1:3000',

    /* Collect trace when retrying the failed test. See https://playwright.dev/docs/trace-viewer */
    trace: 'on-first-retry',
  },
  snapshotPathTemplate: '{testDir}/{testFileDir}/__snapshots__/{arg}{ext}',
  projects: [
    {
      name: 'p0',
      testMatch: ['**/*.p0.spec.{js,ts}'],
      retries: 0,
      use: { ...devices['Desktop Chrome'] },
      reporter: process.env.CI ? [['html', { open: 'never' }], ['github']] : [['html']],
    },
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
      testIgnore: ['**/a11y/**', '**/mobile/**', '**/extra-features.spec.js'],
    },
    {
      name: 'mobile-chrome',
      use: { ...devices['Pixel 5'] },
      testIgnore: ['**/a11y/**', '**/desktop/**', '**/extra-features.spec.js'],
    },
    {
      name: 'a11y-mobile',
      use: { ...devices['Pixel 5'] },
      testDir: './e2e/tests/a11y/mobile',
    },
    {
      name: 'a11y-desktop',
      use: { ...devices['Desktop Chrome'] },
      testDir: './e2e/tests/a11y/desktop',
    },
    {
      name: 'extra-features-desktop',
      testMatch: ['e2e/tests/desktop/extra-features.spec.js'],
      use: { ...devices['Desktop Chrome'] },
    },
    {
      name: 'extra-features-mobile',
      testMatch: ['e2e/tests/mobile/extra-features.spec.js'],
      use: { ...devices['Pixel 5'] },
    },
  ],
});

